كود Room يوضح الحفظ الدائم والمؤكد للمعاملة قبل بدء الاتصال بالشبكة:
```kotlin
@Entity(tableName = "payment_ledger")
data class PaymentRecordEntity(
    @PrimaryKey val transactionId: String,
    val amountCents: Long,
    val currency: String,
    val state: String, // INITIATED, PROCESSING, APPROVED, REVERSED
    val idempotencyKey: String,
    val createdAtTimestamp: Long,
    val authorizationCode: String? = null
)

// الإجراء الهندسي الصارم:
class PaymentRepository(private val db: AppDatabase, private val api: PaymentApi) {
    suspend fun processPayment(request: PaymentRequest): PaymentResult = withContext(Dispatchers.IO) {
        // 1. الحفظ الدائم أولاً على القرص (Durable Commit) قبل الشبكة:
        db.runInTransaction {
            db.paymentDao().insert(PaymentRecordEntity(
                transactionId = request.txId,
                amountCents = request.amount,
                currency = "USD",
                state = "INITIATED",
                idempotencyKey = request.idempotencyKey,
                createdAtTimestamp = System.currentTimeMillis()
            ))
        }

        // 2. الآن فقط يُسمح بفتح اتصال الشبكة بأمان:
        val response = api.charge(request)

        // 3. تحديث الحالة فوراً على القرص:
        db.paymentDao().updateState(request.txId, "APPROVED", response.authCode)
        PaymentResult.Success(response.authCode)
    }
}
```

تطبيق نمط الـ Correlation ID في معمارية تطبيق أندرويد مالي وتمريره في الـ Headers والـ Logs:
```kotlin
// 1. توليد الـ Correlation ID عند بدء تدفق الدفع:
data class PaymentSession(
    val correlationId: String = "tx_" + UUID.randomUUID().toString(),
    val amount: Long,
    val currency: String
)

// 2. حقن المعرف في كل طلب شبكة عبر OkHttp Interceptor:
class CorrelationIdInterceptor(private val sessionManager: SessionManager) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val correlationId = sessionManager.currentCorrelationId ?: "unknown"

        val authenticatedRequest = chain.request().newBuilder()
            .header("X-Correlation-ID", correlationId)
            .header("X-Request-ID", UUID.randomUUID().toString()) // معرف فريد لهذا الطلب الفردي
            .build()

        // 3. تضمين المعرف في سجلات المراقبة المحلية (Structured Logging):
        MDC.put("correlation_id", correlationId) // Logback / SLF4J diagnostic context
        Timber.tag("PaymentFlow").i("Dispatching authorization request for %s", correlationId)

        return chain.proceed(authenticatedRequest)
    }
}
```

تطبيق المعاملات الذرية لحفظ نية العكس في Room باستخدام `@Transaction`:
```kotlin
@Dao
interface PaymentDao {
    @Query("UPDATE transactions SET status = :newStatus WHERE id = :txId")
    suspend fun updateTransactionStatus(txId: String, newStatus: String)

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertReversalIntent(intent: ReversalIntentEntity)

    // ✅ المعاملة الذرية الصارمة: مستحيل تنفيذ خطوة دون الأخرى!
    @Transaction
    suspend fun markInDoubtAndEnqueueReversal(
        txId: String,
        intent: ReversalIntentEntity
    ) {
        updateTransactionStatus(txId, "UNKNOWN_AWAITING_REVERSAL")
        insertReversalIntent(intent)
    }
}

// الاستخدام داخل الـ Repository عند حدوث انقطاع في الشبكة:
suspend fun handleTimeoutFailure(txId: String, request: PaymentRequest) {
    val reversalIntent = ReversalIntentEntity(
        reversalId = UUID.randomUUID().toString(),
        originalTxId = txId,
        amountCents = request.amount,
        payload = request.toIso8583ReversalPayload(),
        status = "PENDING_DISPATCH"
    )
    // الذرية تضمن كتابة كلاهما للقرص معاً:
    paymentDao.markInDoubtAndEnqueueReversal(txId, reversalIntent)
    // إطلاق مهمة WorkManager لمعالجة الطابور:
    reversalWorkScheduler.scheduleReversalWorker()
}
```

تصميم نظام Reversal Queue متكامل يصمد أمام انقطاع الطاقة المفاجئ:
```kotlin
// 1. Worker صامد يعتمد على WorkManager لمعالجة طابور الـ Reversals:
class ReversalDispatchWorker(
    context: Context,
    params: WorkerParameters,
    private val paymentDao: PaymentDao,
    private val paymentApi: PaymentApi
) : CoroutineWorker(context, params) {

    override suspend fun doWork(): Result = withContext(Dispatchers.IO) {
        val pendingReversals = paymentDao.getAllPendingReversals()
        for (reversal in pendingReversals) {
            try {
                val response = paymentApi.sendReversal(reversal.payload)
                if (response.isSuccess) {
                    paymentDao.deleteReversal(reversal.id)
                } else {
                    paymentDao.incrementRetryCount(reversal.id)
                }
            } catch (e: IOException) {
                // خطأ شبكة -> إعادة المحاولة التلقائية وفق Backoff Policy:
                return@withContext Result.retry()
            }
        }
        Result.success()
    }
}

// 2. فحص إلزامي يمنع إجراء أي معاملة جديدة إذا كان هناك Reversal معلق:
class PaymentOrchestrator(private val paymentDao: PaymentDao) {
    suspend fun canInitiateNewPayment(): Boolean {
        val pendingCount = paymentDao.countPendingReversals()
        // إذا نزع الكاشير البطارية وأعاد تشغيلها، نرفض أي دفع جديد حتى تصفية المعلقات:
        return pendingCount == 0
    }
}
```

تنفيذ هندسي متكامل لمنع تكرار طلبات الدفع عبر الطبقات الثلاث:
```kotlin
// 1. في الـ ViewModel: حماية عبر Mutex وحالة المعالجة الأحادية:
class CheckoutViewModel(private val repository: PaymentRepository) : ViewModel() {
    private val paymentMutex = Mutex()
    private val _uiState = MutableStateFlow<CheckoutUiState>(CheckoutUiState.Idle)
    val uiState: StateFlow<CheckoutUiState> = _uiState.asStateFlow()

    fun onPayClicked(orderId: String, amount: Long) {
        viewModelScope.launch {
            // حماية Mutex: إذا كان هناك دفع جاري، يتم تجاهل النقرة فوراً:
            if (!paymentMutex.tryLock()) return@launch
            try {
                _uiState.value = CheckoutUiState.Processing
                val result = repository.executePayment(orderId, amount)
                _uiState.value = CheckoutUiState.Success(result)
            } catch (e: Exception) {
                _uiState.value = CheckoutUiState.Error(e.message ?: "Payment failed")
            } finally {
                paymentMutex.unlock()
            }
        }
    }
}

// 2. في واجهة Compose: زر معطل ومحمي ضد النقر المتكرر:
@Composable
fun CheckoutScreen(viewModel: CheckoutViewModel) {
    val state by viewModel.uiState.collectAsStateWithLifecycle()
    val isProcessing = state is CheckoutUiState.Processing

    Button(
        onClick = { viewModel.onPayClicked("ord_123", 5000) },
        enabled = !isProcessing // تعطيل الزر فورياً عند بدء الدفع
    ) {
        if (isProcessing) {
            CircularProgressIndicator(modifier = Modifier.size(24.dp))
        } else {
            Text("Pay $50.00")
        }
    }
}
