اختبار كامل في كوتلن يحاكي انقطاع العتاد ونفاد الوقت ويتحقق من إطلاق الـ Reversal:
```kotlin
class PaymentOrchestratorTest {
    private val fakeCardReader = FakeCardReaderManager()
    private val paymentDao = FakePaymentDao()
    private val orchestrator = PaymentOrchestrator(fakeCardReader, paymentDao)

    @Test
    fun `card reader timeout enqueues reversal and aborts transaction`() = runTest {
        // 1. ضبط الـ Fake لمحاكاة الصمت التام (عدم الرد):
        fakeCardReader.shouldSimulateTimeout = true

        val job = launch {
            orchestrator.processCardPayment(amountCents = 10000)
        }

        // 2. تقديم الوقت الافتراضي لـ 30 ثانية لتجاوز مهلة الـ Timeout:
        advanceTimeBy(30_001)

        // 3. التحقق من أن النظام رصد الـ Timeout وعكس العملية:
        val pendingReversals = paymentDao.getAllPendingReversals()
        assertEquals(1, pendingReversals.size)
        assertEquals(10000, pendingReversals.first().amountCents)
        assertEquals("TIMEOUT_REVERSAL", pendingReversals.first().reason)
        job.cancel()
    }

    @Test
    fun `abrupt usb disconnect during pin entry emits reader error`() = runTest {
        val events = mutableListOf<CardReaderEvent>()
        val collectJob = launch {
            fakeCardReader.startCardInteraction(5000).collect { events.add(it) }
        }

        fakeCardReader.emitEvent(CardReaderEvent.PinRequired)
        // محاكاة فصل الكابل فجأة أثناء كتابة الـ PIN:
        fakeCardReader.simulateDisconnection()

        val lastEvent = events.last()
        assertTrue(lastEvent is CardReaderEvent.ReaderError)
        assertEquals(999, (lastEvent as CardReaderEvent.ReaderError).errorCode)
        collectJob.cancel()
    }
}
```

مخطط منطق التعافي الآلي عند إقلاع تطبيق أندرويد POS بعد انقطاع الطاقة:
```kotlin
class StartupRecoveryManager(
    private val paymentDao: PaymentDao,
    private val gatewayApi: PaymentGatewayApi,
    private val receiptPrinter: ReceiptPrinter
) {
    suspend fun recoverInDoubtTransactionsOnBoot() = withContext(Dispatchers.IO) {
        // 1. استخراج أي معاملات كانت قيد المعالجة ولم تكتمل:
        val strandedTransactions = paymentDao.getTransactionsByState("PROCESSING")

        for (tx in strandedTransactions) {
            try {
                // 2. الاستعلام عن حالة العملية لدى خادم الدفع باستخدام نفس الـ ID:
                val statusResponse = gatewayApi.queryTransactionStatus(tx.idempotencyKey)

                if (statusResponse.isApproved) {
                    // تم الخصم بنجاح: تأكيد محلي وطباعة إيصال التعافي:
                    paymentDao.markApproved(tx.id, statusResponse.authCode)
                    receiptPrinter.printDuplicateReceipt(tx, statusResponse.authCode)
                } else {
                    // لم تكتمل في البنك: إطلاق Reversal لتنظيف أي حجز معلق:
                    gatewayApi.sendReversal(tx.toReversalPayload())
                    paymentDao.markReversed(tx.id)
                    receiptPrinter.printReversalNotice(tx)
                }
            } catch (e: Exception) {
                // تعذر الاتصال بالخادم: إدراجها في Reversal Queue للمطابقة لاحقاً:
                paymentDao.markAwaitingReconciliation(tx.id)
            }
        }
    }
}
```

إعادة هيكلة الملكية والترتيب لمنع فقدان الـ Reversals نهائياً:
```kotlin
// 1. خدمة ذات نطاق عام (Application Scope) تملك دورة حياة المعاملة وتصمد أمام إغلاق الشاشات:
@Singleton
class PaymentEngine @Inject constructor(
    @ApplicationScope private val externalScope: CoroutineScope,
    private val paymentDao: PaymentDao,
    private val paymentApi: PaymentApi,
    private val workScheduler: ReversalWorkScheduler
) {
    private val _txState = MutableSharedFlow<PaymentState>(replay = 1)
    val txState: SharedFlow<PaymentState> = _txState.asSharedFlow()

    fun executePaymentWithGuaranteedReversal(txId: String, request: PaymentRequest) {
        // يتم الإطلاق في ApplicationScope: حتى لو ماتت الـ Activity بالكامل، الكود يكمل تنفيذه!
        externalScope.launch {
            try {
                withTimeout(30_000L) {
                    val response = paymentApi.authorize(request)
                    paymentDao.markApproved(txId, response.authCode)
                    _txState.emit(PaymentState.Approved(response.authCode))
                }
            } catch (e: TimeoutCancellationException) {
                // ✅ الترتيب الحاسم: الحفظ الدائم على القرص أولاً وقبل إبلاغ الواجهة!
                paymentDao.markInDoubtAndEnqueueReversal(txId, request.toReversalPayload())
                workScheduler.triggerReversalWork()

                // الآن فقط نخبر الواجهة بأن العملية انتهت بمهلة وعكست بأمان:
                _txState.emit(PaymentState.TimedOutAndReversed(txId))
            }
        }
    }
}
```

